class Solution:
    def reportingChain(self, employees):
        mgr = {e[0]: e[2] for e in employees}
        res = []
        for eid in mgr:
            cur, ok = eid, False
            for _ in range(4):
                if cur == 1:
                    ok = True
                    break
                if cur not in mgr or mgr[cur] == cur:
                    break
                cur = mgr[cur]
            if ok and eid != 1:
                res.append(eid)
        return res

