// SQL problem — C++ shown as equivalent simulation.
class Solution {
public:
    vector<int> reportingChain(vector<vector<int>>& employees) {
        unordered_map<int,int> mgr;
        for (auto& e : employees) mgr[e[0]] = e[2];
        vector<int> res;
        for (auto& [eid, m] : mgr) {
            int cur = eid; bool ok = false;
            for (int i = 0; i < 4 && !ok; i++) {
                if (cur == 1) ok = true;
                else if (!mgr.count(cur) || mgr[cur] == cur) break;
                else cur = mgr[cur];
            }
            if (ok && eid != 1) res.push_back(eid);
        }
        return res;
    }
};

