// SQL problem — Java shown as equivalent simulation.
class Solution {
    public List<Integer> reportingChain(int[][] employees) {
        Map<Integer, Integer> mgr = new HashMap<>();
        for (int[] e : employees) mgr.put(e[0], e[2]);
        List<Integer> res = new ArrayList<>();
        for (int eid : mgr.keySet()) {
            int cur = eid; boolean ok = false;
            for (int i = 0; i < 4 && !ok; i++) {
                if (cur == 1) ok = true;
                else if (!mgr.containsKey(cur) || mgr.get(cur) == cur) break;
                else cur = mgr.get(cur);
            }
            if (ok && eid != 1) res.add(eid);
        }
        return res;
    }
}

