// SQL problem — JS shown as equivalent simulation.
var reportingChain = function(employees) {
    const mgr = new Map();
    for (const [eid, , mid] of employees) mgr.set(eid, mid);
    const res = [];
    for (const eid of mgr.keys()) {
        let cur = eid, ok = false;
        for (let i = 0; i < 4 && !ok; i++) {
            if (cur === 1) ok = true;
            else if (!mgr.has(cur) || mgr.get(cur) === cur) break;
            else cur = mgr.get(cur);
        }
        if (ok && eid !== 1) res.push(eid);
    }
    return res;
};
